widget.solution:
import numpy as np

def test_r2(y_train, y_test, pred):
    y_train, y_test, pred = (np.asarray(a, dtype=float) for a in (y_train, y_test, pred))
    mse_model = np.mean((y_test - pred) ** 2)
    mse_base = np.mean((y_test - y_train.mean()) ** 2)
    return round(float(1 - mse_model / mse_base), 6)
